select
  id, study_id, patient_id, exam_no, test_no, create_time, update_time, result_time, abnormal_indicator_high, abnormal_indicator_low, total_cholesterol, triglycerides, hdl_cholesterol, apolipoprotein_a1, apolipoprotein_b, ldl_cholesterol
from td_blood_fat_items


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and total_cholesterol = #{totalCholesterol}


        and triglycerides = #{triglycerides}


        and hdl_cholesterol = #{hdlCholesterol}


        and apolipoprotein_a1 = #{apolipoproteinA1}


        and apolipoprotein_b = #{apolipoproteinB}


        and ldl_cholesterol = #{ldlCholesterol}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_blood_fat_items


